#pragma once
#include "s3_event_time.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
namespace hanmo::resident::s3_event_time_codec {
template<class A>Status source(A&a,SourceRef&r){a.field("domain",r.domain);a.field("kind",r.kind);return a.field("id",r.id);}
template<class A>Status record(A&a,S3EventRecordRef&r){Integer tag=static_cast<Integer>(r.index());a.field("tag",tag);if(!a.status().ok)return a.status();if(tag<0||tag>7)return a.reject("InvalidS3EventRecordTag");if(a.reading()){switch(tag){case 0:{if(!prepare_checkpoint_default_values<S3PersonalAppointmentRecord>(a).ok)return a.status();r=S3PersonalAppointmentRecord{};}break;case 1:{if(!prepare_checkpoint_default_values<S3ContactInquiryRecord>(a).ok)return a.status();r=S3ContactInquiryRecord{};}break;case 2:{if(!prepare_checkpoint_default_values<S3VisitAppointmentMeetingRecord>(a).ok)return a.status();r=S3VisitAppointmentMeetingRecord{};}break;case 3:{if(!prepare_checkpoint_default_values<S3InteractionStepRecord>(a).ok)return a.status();r=S3InteractionStepRecord{};}break;case 4:{if(!prepare_checkpoint_default_values<S3ProfessionalInstallmentRecord>(a).ok)return a.status();r=S3ProfessionalInstallmentRecord{};}break;case 5:{if(!prepare_checkpoint_default_values<S3ProfessionalCustodyReturnRecord>(a).ok)return a.status();r=S3ProfessionalCustodyReturnRecord{};}break;case 6:{if(!prepare_checkpoint_default_values<S3ResidualCopyDeliveryRecord>(a).ok)return a.status();r=S3ResidualCopyDeliveryRecord{};}break;default:{if(!prepare_checkpoint_default_values<S3ProfessionalResultDeliveryRecord>(a).ok)return a.status();r=S3ProfessionalResultDeliveryRecord{};}}}
 return std::visit([&](auto&v)->Status{using T=std::decay_t<decltype(v)>;
 if constexpr(std::is_same_v<T,S3PersonalAppointmentRecord>||std::is_same_v<T,S3ContactInquiryRecord>||std::is_same_v<T,S3VisitAppointmentMeetingRecord>){constexpr Integer max=std::is_same_v<T,S3PersonalAppointmentRecord>?3:std::is_same_v<T,S3ContactInquiryRecord>?1:2;dynamic_codec::enumeration(a,"record_table",v.record_table,max);return a.field("record_id",v.record_id);}
 else if constexpr(std::is_same_v<T,S3InteractionStepRecord>){a.field("original_session_id",v.original_session_id);return a.field("original_step_execution_key",v.original_step_execution_key);}
 else {a.field("order_id",v.order_id);if constexpr(std::is_same_v<T,S3ProfessionalInstallmentRecord>)return a.field("installment_result_id",v.installment_result_id);else if constexpr(std::is_same_v<T,S3ProfessionalCustodyReturnRecord>)return a.field("return_result_id",v.return_result_id);else if constexpr(std::is_same_v<T,S3ResidualCopyDeliveryRecord>)return a.field("residual_delivery_result_id",v.residual_delivery_result_id);else return a.field("result_delivery_result_id",v.result_delivery_result_id);}},r);
}
template<class A>Status actual(A&a,S3EventActualSource&s){Integer tag=static_cast<Integer>(s.index());a.field("tag",tag);if(!a.status().ok)return a.status();if(tag<0||tag>4)return a.reject("InvalidS3EventActualSourceTag");if(a.reading()){switch(tag){case 0:{if(!prepare_checkpoint_default_values<S3ActionStartedSource>(a).ok)return a.status();s=S3ActionStartedSource{};}break;case 1:{if(!prepare_checkpoint_default_values<S3ActionFinishedSource>(a).ok)return a.status();s=S3ActionFinishedSource{};}break;case 2:{if(!prepare_checkpoint_default_values<S3CommittedZeroStepSource>(a).ok)return a.status();s=S3CommittedZeroStepSource{};}break;case 3:{if(!prepare_checkpoint_default_values<S3ActualTerminationSource>(a).ok)return a.status();s=S3ActualTerminationSource{};}break;default:{if(!prepare_checkpoint_default_values<S3ReceivedKnowledgeSource>(a).ok)return a.status();s=S3ReceivedKnowledgeSource{};}}}
 return std::visit([&](auto&v)->Status{using T=std::decay_t<decltype(v)>;
 if constexpr(std::is_same_v<T,S3ActionStartedSource>){a.field("action_id",v.action_id);return a.object("original_start_result_ref",[&](auto&c){return source(c,v.original_start_result_ref);});}
 else if constexpr(std::is_same_v<T,S3ActionFinishedSource>){a.field("action_id",v.action_id);return a.object("original_completion_result_ref",[&](auto&c){return source(c,v.original_completion_result_ref);});}
 else if constexpr(std::is_same_v<T,S3CommittedZeroStepSource>){a.object("original_commit_result_ref",[&](auto&c){return source(c,v.original_commit_result_ref);});return a.object("actual_contact_source_ref",[&](auto&c){return source(c,v.actual_contact_source_ref);});}
 else if constexpr(std::is_same_v<T,S3ActualTerminationSource>){a.object("original_cause_ref",[&](auto&c){return source(c,v.original_cause_ref);});return a.optional("original_action_terminal_ref",v.original_action_terminal_ref,[](auto&c,auto&r){return source(c,r);});}
 else return a.object("original_knowledge_receipt_ref",[&](auto&c){return source(c,v.original_knowledge_receipt_ref);});},s);
}
template<class A>Status fields(A&a,S3EventTime&v){a.object("original_record_ref",[&](auto&c){return record(c,v.original_record_ref);});dynamic_codec::enumeration(a,"event_role",v.event_role,9);a.object("precision",[&](auto&c){Integer tag=static_cast<Integer>(v.precision.index());c.field("tag",tag);if(!c.status().ok)return c.status();if(tag<0||tag>1)return c.reject("InvalidS3EventPrecision");if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<S3LegacyEventTick>(c).ok)return c.status();v.precision=S3LegacyEventTick{};}else{if(!prepare_checkpoint_default_values<S3ExactEventMoment>(c).ok)return c.status();v.precision=S3ExactEventMoment{};}}if(tag==0)return c.status();auto&x=std::get<S3ExactEventMoment>(v.precision);c.object("occurred_at",[&](auto&m){return dynamic_codec::exact_moment(m,x.occurred_at);});return c.object("actual_source",[&](auto&m){return actual(m,x.actual_source);});});if(!a.status().ok)return a.status();return validate_s3_event_time_shape(v);}
}
